using System.Security.Claims; using MaintenancePRO.Api.Contracts; using MaintenancePRO.Api.Data; using MaintenancePRO.Api.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace MaintenancePRO.Api.Controllers;
[ApiController,Route("api/breakdowns"),Authorize]
public sealed class BreakdownsController(AppDbContext db):ControllerBase {
 [HttpGet] public async Task<IActionResult> List([FromQuery]BreakdownStatus? status,[FromQuery]BreakdownSeverity? severity,[FromQuery]int page=1,[FromQuery]int pageSize=20){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Breakdowns.AsNoTracking().Include(x=>x.Equipment).AsQueryable();var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);if(User.IsInRole(AppRoles.User))q=q.Where(x=>x.ReportedByUserId==uid);if(User.IsInRole(AppRoles.Technician))q=q.Where(x=>x.Interventions.Any(i=>i.AssignedTechnicianId==uid)||x.ReportedByUserId==uid);if(status.HasValue)q=q.Where(x=>x.Status==status);if(severity.HasValue)q=q.Where(x=>x.Severity==severity);var total=await q.CountAsync();return Ok(new{page,pageSize,total,items=await q.OrderByDescending(x=>x.ReportedUtc).Skip((page-1)*pageSize).Take(pageSize).ToListAsync()});}
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var x=await db.Breakdowns.AsNoTracking().Include(x=>x.Equipment).Include(x=>x.Diagnoses).Include(x=>x.Interventions).Include(x=>x.Photos).FirstOrDefaultAsync(x=>x.Id==id);if(x==null)return NotFound();if(!CanRead(x))return Forbid();return Ok(x);}
 [HttpPost] public async Task<IActionResult> Create(CreateBreakdownRequest r){if(!await db.Equipments.AnyAsync(x=>x.Id==r.EquipmentId&&x.Status!=EquipmentStatus.Retired))return BadRequest(new{message="Équipement inconnu ou archivé."});var uid=User.FindFirstValue(ClaimTypes.NameIdentifier)!;var x=new Breakdown{EquipmentId=r.EquipmentId,Title=r.Title.Trim(),Description=r.Description.Trim(),Severity=r.Severity,ReportedByUserId=uid};db.Breakdowns.Add(x);var eq=await db.Equipments.FindAsync(r.EquipmentId);if(eq!=null){eq.Status=EquipmentStatus.Broken;eq.UpdatedUtc=DateTime.UtcNow;}Audit("BreakdownReported",x.Id.ToString());await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=x.Id},x);}
 [HttpPatch("{id:int}/status"),Authorize(Policy="ManageMaintenance")] public async Task<IActionResult> SetStatus(int id,[FromBody]BreakdownStatus status){var x=await db.Breakdowns.Include(x=>x.Equipment).FirstOrDefaultAsync(x=>x.Id==id);if(x==null)return NotFound();if(!Allowed(x.Status,status))return Conflict(new{message="Transition de panne non autorisée."});x.Status=status;if(status==BreakdownStatus.Resolved){x.ResolvedUtc=DateTime.UtcNow;if(x.Equipment!=null){x.Equipment.Status=EquipmentStatus.Available;x.Equipment.UpdatedUtc=DateTime.UtcNow;}}Audit("BreakdownStatusChanged",id.ToString());await db.SaveChangesAsync();return Ok(x);}
 private bool CanRead(Breakdown x){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);return User.IsInRole(AppRoles.Admin)||User.IsInRole(AppRoles.Supervisor)||x.ReportedByUserId==uid||(User.IsInRole(AppRoles.Technician)&&x.Interventions.Any(i=>i.AssignedTechnicianId==uid));}
 private static bool Allowed(BreakdownStatus a,BreakdownStatus b)=>a switch{BreakdownStatus.Reported=>b is BreakdownStatus.Diagnosing or BreakdownStatus.Rejected,BreakdownStatus.Diagnosing=>b is BreakdownStatus.AwaitingApproval or BreakdownStatus.InMaintenance or BreakdownStatus.Rejected,BreakdownStatus.AwaitingApproval=>b is BreakdownStatus.InMaintenance or BreakdownStatus.Rejected,BreakdownStatus.InMaintenance=>b is BreakdownStatus.Resolved or BreakdownStatus.Diagnosing,BreakdownStatus.Resolved=>b==BreakdownStatus.Closed,_=>false};
 private void Audit(string a,string id)=>db.AuditEvents.Add(new AuditEvent{ActorUserId=User.FindFirstValue(ClaimTypes.NameIdentifier),Action=a,EntityType="Breakdown",EntityId=id,IpAddress=HttpContext.Connection.RemoteIpAddress?.ToString()});
}
